// TH18 v1.00a Stage 4 midstage w09, MainSub06 (st04.ecl.txt:1010-1026)
// and Cir03 (st04.ecl.txt:216-282). Source x/y and rad values kept.
const TIME_LIMIT: int = 2100; // 120-frame shell buffer + ~1980 source frames
const TH18_BALL2: int = 432; // source type 5, color 4 -> appearance 436

// st04.ecl.txt:247-262: ANIM(1), WAIT60, then VELTIME 120 to the rank speed.
// The WAIT60 serves the birth ANIM and is omitted with the approved whole
// birth-stage omission; VELTIME therefore starts at bullet birth.
// type 0x200000: a=120, r=(2.0/2.5/3.5), s=-1000000 -> keep current bullet angle.
xformdef TH18_VEL_E { set_accel((2.0fx - 0.8fx) / 120); wait(120); set_accel(0fx); }
xformdef TH18_VEL_H { set_accel((2.5fx - 0.8fx) / 120); wait(120); set_accel(0fx); }
xformdef TH18_VEL_L { set_accel((3.5fx - 0.8fx) / 120); wait(120); set_accel(0fx); }

// Cir03_at, st04.ecl.txt:241-281. Async first run = next frame after the call,
// then wait(120), matching source callAsync timing.
async sub cir03_attack() {
    wait(120);
    var rank: int = global(GVAR_RANK);
    // etCount(0, [-1], 1) stack branch, st04.ecl.txt:248-257: 1/3/5/7 ways.
    var ways: int = 1;
    // diffI($A, 20, 30, 40, 60), st04.ecl.txt:273: number of 5-frame volleys.
    var volleys: int = 20;
    if rank == 1 { ways = 3; volleys = 30; }
    if rank == 2 { ways = 5; volleys = 40; }
    if rank == 3 { ways = 7; volleys = 60; }
    // st04.ecl.txt:245-259 etNew/etAim(0)/etSprite(5,4)/etCount/
    // etAngle(0, 0.06981317 rad = 4deg)/etSpeed(0.8, 1.0).
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, 4);
    sh_aim(0, 1); // mode 0 aimed fan
    sh_ring(0, 0);
    sh_count(0, ways, 1);
    sh_angle(0, 0deg, 4deg);
    sh_speed(0, 0.8fx, 0fx);
    if rank <= 1 { sh_xform(0, TH18_VEL_E); }
    if rank == 2 { sh_xform(0, TH18_VEL_H); }
    if rank == 3 { sh_xform(0, TH18_VEL_L); }
    // st04.ecl.txt:274-279: etOn then wait(5), $A times including last wait.
    for i in 0..volleys {
        sh_fire(0);
        wait(5);
    }
}

// Cir03, st04.ecl.txt:216-239. Frame 28/16 boxes are kept (target radii = source/2).
async sub cir03_main() {
    set_hurtbox(14fx); // source 28x28
    set_hitbox(8fx);   // source 16x16
    // st04.ecl.txt:226-228 moveVel(pi/2,5.0), moveAngleTime(120,4,ANGLE_PLAYER),
    // moveSpeedTime(120,0,0.1). Mode 4 = EASE_QUAD_OUT, mode 0 = EASE_LINEAR.
    move_vel(0, 90deg, 5.0fx, EASE_LINEAR);
    move_angle(120, aim_player(), EASE_QUAD_OUT);
    move_speed(120, 0.1fx, EASE_LINEAR);
    spawn cir03_attack();
    wait(180);
    // st04.ecl.txt:231-232 moveAngleTime(120,6,ANGLE_PLAYER),
    // moveSpeedTime(120,0,-2.0). Mode 6 = EASE_QUART_OUT.
    move_angle(120, aim_player(), EASE_QUART_OUT);
    move_speed(120, -2.0fx, EASE_LINEAR);
    loop { wait(1); }
}

// MainSub06, st04.ecl.txt:1010-1026. 16 rounds, right then left 40 frames apart;
// F0=%RANDRAD is never read by Cir03, so only the two RANDF2 x draws are kept.
async sub wave() {
    wait(120); // task-mandated opening buffer
    for r in 0..16 {
        var xr: fx = 128fx + ((rand(65536) - 32768) as fx) / 1024fx;
        _ = spawn_enemy(xr, -32fx, 500, 0, 0, 0, cir03_main);
        wait(40);
        var xl: fx = -128fx + ((rand(65536) - 32768) as fx) / 1024fx;
        _ = spawn_enemy(xl, -32fx, 500, 0, 0, 0, cir03_main);
        wait(40);
    }
}

// Invincible practice control enemy at (0,0) with body collision disabled;
// real Cir03 enemies above keep their source hitboxes.
async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    loop { wait(600); }
}
